from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Initialize an empty list to store the extracted groups
    extracted_groups = []

    # Iterate through the input string and identify groups of nested parentheses
    stack = []
    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                extracted_groups.append(paren_string[start:i+1])

    # Check if the identified groups are balanced and not nested within each other
    def is_balanced(group):
        count = 0
        for char in group:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count < 0:
                return False
        return count == 0

    # Add the valid groups to the list
    valid_groups = [group for group in extracted_groups if is_balanced(group)]

    # Return the list of extracted groups
    return valid_groups
